1	package incidents
2	
3	// Load applies one durable record recovered during startup. It rebuilds the
4	// exact committed state, including the server timestamps the first run
5	// assigned, so history order and times are preserved across restarts. Every
6	// record is assumed to have passed DecodeRecord's validation; a record that
7	// contradicts the already-loaded state (duplicate creation, unknown
8	// incident, action id reuse, non-sequential version) is an error that should
9	// fail startup rather than mutate data.
10	func (r *Registry) Load(record Record) error {
11		r.mu.Lock()
12		defer r.mu.Unlock()
13	
14		at := record.At.UTC()
15		switch record.Kind {
16		case RecordCreation:
17			c := *record.Creation
18			if _, exists := r.incidents[c.ID]; exists {
19				return validationErr("duplicate creation for incident %q in log", c.ID)
20			}
21			r.incidents[c.ID] = newIncidentState(c, at)
22			return nil
23	
24		case RecordAction:
25			req := record.Action.Request
26			state, ok := r.incidents[req.IncidentID]
27			if !ok {
28				return validationErr("action for unknown incident %q in log", req.IncidentID)
29			}
30			if _, dup := state.actions[req.ActionID]; dup {
31				return validationErr("duplicate action %q in incident %q log", req.ActionID, req.IncidentID)
32			}
33			// The durable request's expected_version is the version in force
34			// just before the action; the resulting version must follow in
35			// lockstep. Checking it catches any reordered or missing frames.
36			if req.ExpectedVersion != state.version {
37				return validationErr("action %q expected version %d but log was at %d",
38					req.ActionID, req.ExpectedVersion, state.version)
39			}
40			if err := r.checkLoadedAction(state, req); err != nil {
41				return err
42			}
43			state.commit(req, at)
44			return nil
45	
46		default:
47			return validationErr("unknown record kind %q in log", record.Kind)
48		}
49	}
50	
51	// checkLoadedAction mirrors the live state-machine and link checks. Events
52	// are never removed, so an event linked at action time must still resolve and
53	// still match the incident's service; a failure means the log is internally
54	// inconsistent and must abort startup rather than mutate data.
55	func (r *Registry) checkLoadedAction(state *incidentState, req Request) error {
56		switch req.Type {
57		case ActionNote:
58			if state.status != StatusOpen {
59				return validationErr("note action %q on %s incident in log", req.ActionID, state.status)
60			}
61		case ActionLinkEvent:
62			if state.status != StatusOpen {
63				return validationErr("link action %q on %s incident in log", req.ActionID, state.status)
64			}
65			if _, linked := state.linkSet[req.Content]; linked {
66				return validationErr("event %q linked twice in incident %q log", req.Content, state.id)
67			}
68			if r.events == nil {
69				return validationErr("event %q missing while replaying incident log", req.Content)
70			}
71			service, found := r.events.LookupEvent(req.Content)
72			if !found {
73				return validationErr("linked event %q no longer exists in the event log", req.Content)
74			}
75			if service != state.service {
76				return validationErr("linked event %q service %q does not match incident %q service %q",
77					req.Content, service, state.id, state.service)
78			}
79		case ActionResolve:
80			if state.status != StatusOpen {
81				return validationErr("resolve action %q on non-open incident in log", req.ActionID)
82			}
83		case ActionReopen:
84			if state.status != StatusResolved {
85				return validationErr("reopen action %q on non-resolved incident in log", req.ActionID)
86			}
87		case ActionAddParticipant:
88			if state.status != StatusOpen {
89				return validationErr("add_participant action %q on %s incident in log", req.ActionID, state.status)
90			}
91			if _, member := state.participantSet[req.Content]; member {
92				return validationErr("participant %q added twice in incident %q log", req.Content, state.id)
93			}
94		case ActionRemoveParticipant:
95			if state.status != StatusOpen {
96				return validationErr("remove_participant action %q on %s incident in log", req.ActionID, state.status)
97			}
98			if _, member := state.participantSet[req.Content]; !member {
99				return validationErr("participant %q removed without joining in incident %q log", req.Content, state.id)
100			}
101			if req.Content == state.owner {
102				return validationErr("current owner %q removed in incident %q log", req.Content, state.id)
103			}
104		case ActionAssignOwner:
105			if state.status != StatusOpen {
106				return validationErr("assign_owner action %q on %s incident in log", req.ActionID, state.status)
107			}
108			if _, member := state.participantSet[req.Content]; !member {
109				return validationErr("incident %q handed to non-participant %q in log", state.id, req.Content)
110			}
111			if req.Content == state.owner {
112				return validationErr("owner %q handed over to itself in incident %q log", req.Content, state.id)
113			}
114		default:
115			return validationErr("unknown action %q in log", req.Type)
116		}
117		return nil
118	}
