1	// Package incidents holds the incident-handling register: incidents are
2	// created once, evolve through append-only actions under optimistic
3	// concurrency, and link back to events without modifying them.
4	package incidents
5	
6	import (
7		"errors"
8		"fmt"
9		"slices"
10		"strings"
11		"sync"
12		"time"
13	)
14	
15	// Incident statuses.
16	const (
17		StatusOpen     = "open"
18		StatusResolved = "resolved"
19	)
20	
21	// Actions accepted by POST /incidents/{id}/actions. ActionCreate marks the
22	// creation entry in an incident's history.
23	const (
24		ActionCreate            = "create"
25		ActionNote              = "add_note"
26		ActionLinkEvent         = "link_event"
27		ActionResolve           = "resolve"
28		ActionReopen            = "reopen"
29		ActionAddParticipant    = "add_participant"
30		ActionRemoveParticipant = "remove_participant"
31		ActionAssignOwner       = "assign_owner"
32	)
33	
34	// ValidationError reports missing fields, wrong types, or unknown actions.
35	type ValidationError struct{ Reason string }
36	
37	func (e *ValidationError) Error() string { return e.Reason }
38	
39	// NotFoundError reports a missing incident or a missing linked event.
40	type NotFoundError struct{ Reason string }
41	
42	func (e *NotFoundError) Error() string { return e.Reason }
43	
44	// ConflictError carries the current incident version alongside the reason,
45	// so a stale-version response can report it. CurrentVersion is zero when the
46	// conflict is not version-related.
47	type ConflictError struct {
48		Reason         string
49		CurrentVersion int
50	}
51	
52	func (e *ConflictError) Error() string { return e.Reason }
53	
54	// IsValidationError reports whether err is an incident validation failure.
55	func IsValidationError(err error) bool {
56		var target *ValidationError
57		return errors.As(err, &target)
58	}
59	
60	// IsNotFoundError reports whether err is a missing-incident/event failure.
61	func IsNotFoundError(err error) bool {
62		var target *NotFoundError
63		return errors.As(err, &target)
64	}
65	
66	// IsConflictError reports whether err is an incident conflict failure.
67	func IsConflictError(err error) bool {
68		var target *ConflictError
69		return errors.As(err, &target)
70	}
71	
72	// CurrentVersionOf returns the version reported with a version conflict, or
73	// zero when err is not a version conflict.
74	func CurrentVersionOf(err error) int {
75		var target *ConflictError
76		if errors.As(err, &target) {
77			return target.CurrentVersion
78		}
79		return 0
80	}
81	
82	func validationErr(format string, args ...any) error {
83		return &ValidationError{Reason: fmt.Sprintf(format, args...)}
84	}
85	
86	func notFoundErr(format string, args ...any) error {
87		return &NotFoundError{Reason: fmt.Sprintf(format, args...)}
88	}
89	
90	func conflictErr(currentVersion int, format string, args ...any) error {
91		return &ConflictError{Reason: fmt.Sprintf(format, args...), CurrentVersion: currentVersion}
92	}
93	
94	// Creation is the normalized content of POST /incidents. Strings are trimmed
95	// of surrounding whitespace but keep their interior case.
96	type Creation struct {
97		ID       string
98		Title    string
99		Service  string
100		Operator string
101	}
102	
103	// Request is the normalized content of POST /incidents/{id}/actions. Content
104	// carries the action payload: the note text, the linked event id, or the
105	// resolve/reopen reason.
106	type Request struct {
107		IncidentID      string
108		ActionID        string
109		Operator        string
110		ExpectedVersion int
111		Type            string
112		Content         string
113	}
114	
115	// CreateResult is the result of a successful create, including an idempotent
116	// replay.
117	type CreateResult struct {
118		ID      string
119		Status  string
120		Version int
121	}
122	
123	// ActionResult is the result of a successful action, including an idempotent
124	// replay.
125	type ActionResult struct {
126		IncidentID string
127		ActionID   string
128		Version    int
129	}
130	
131	// Entry is one committed item in an incident's history: the creation itself
132	// or a later action.
133	type Entry struct {
134		ActionID string
135		Operator string
136		Action   string
137		Content  string
138		Version  int
139		At       time.Time
140	}
141	
142	// Incident is one committed snapshot, suitable for a single-version read.
143	type Incident struct {
144		ID           string
145		Title        string
146		Service      string
147		Status       string
148		Version      int
149		Participants []string
150		Owner        string
151		Links        []string
152		History      []Entry
153	}
154	
155	// EventLookup resolves an event id without exposing the whole timeline, so
156	// incident handling never modifies events.
157	type EventLookup interface {
158		// LookupEvent returns (service, true) for a stored event, or ("", false).
159		LookupEvent(id string) (service string, ok bool)
160	}
161	
162	// BeforeCommit persists one new record while the registry lock is held and
163	// before the in-memory state advances. Returning an error rejects the request
164	// without touching the incident.
165	type BeforeCommit func(record Record) error
166	
167	// Registry is the concurrency-safe set of incidents.
168	type Registry struct {
169		mu        sync.Mutex
170		incidents map[string]*incidentState
171	
172		events       EventLookup
173		beforeCommit BeforeCommit
174		now          func() time.Time
175	}
176	
177	// incidentState is the mutable state of one incident.
178	type incidentState struct {
179		id      string
180		title   string
181		service string
182		status  string
183		version int
184	
185		// participants holds every participant name in membership order; the
186		// membership is tracked separately by participantSet. The owner is always
187		// among the participants. A newly created incident starts with only its
188		// operator as both participant and owner; note/link operators never join
189		// automatically.
190		participants   []string
191		participantSet map[string]struct{}
192		owner          string
193	
194		links   []string
195		linkSet map[string]struct{}
196	
197		history []Entry
198		// actions remembers each successful action's normalized request and the
199		// version reached afterwards, so an identical retry replays the first
200		// result even once the version has moved on.
201		actions map[string]committedAction
202	
203		creation Creation
204	}
205	
206	type committedAction struct {
207		request       Request
208		resultVersion int
209	}
210	
211	// Option configures a Registry at construction.
212	type Option func(*Registry)
213	
214	// WithClock overrides the server clock, mainly for tests.
215	func WithClock(now func() time.Time) Option {
216		return func(r *Registry) {
217			if now != nil {
218				r.now = now
219			}
220		}
221	}
222	
223	// NewRegistry returns an empty registry. events resolves linked event ids and
224	// beforeCommit durably stores each accepted record.
225	func NewRegistry(events EventLookup, beforeCommit BeforeCommit, opts ...Option) *Registry {
226		r := &Registry{
227			incidents:    make(map[string]*incidentState),
228			events:       events,
229			beforeCommit: beforeCommit,
230			now:          func() time.Time { return time.Now().UTC() },
231		}
232		for _, opt := range opts {
233			opt(r)
234		}
235		return r
236	}
237	
238	// NormalizeCreation trims the four creation fields, keeping their interior
239	// case, and requires each to be non-empty afterwards.
240	func NormalizeCreation(input Creation) (Creation, error) {
241		var err error
242		if input.ID, err = trimRequired("id", input.ID); err != nil {
243			return Creation{}, err
244		}
245		if input.Title, err = trimRequired("title", input.Title); err != nil {
246			return Creation{}, err
247		}
248		if input.Service, err = trimRequired("service", input.Service); err != nil {
249			return Creation{}, err
250		}
251		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
252			return Creation{}, err
253		}
254		return input, nil
255	}
256	
257	// NormalizeRequest trims and validates one action request. incidentID comes
258	// from the URL path and is only checked for emptiness.
259	func NormalizeRequest(input Request) (Request, error) {
260		var err error
261		if input.IncidentID, err = trimRequired("incident id", input.IncidentID); err != nil {
262			return Request{}, err
263		}
264		if input.ActionID, err = trimRequired("action_id", input.ActionID); err != nil {
265			return Request{}, err
266		}
267		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
268			return Request{}, err
269		}
270		if input.ExpectedVersion <= 0 {
271			return Request{}, validationErr("expected_version must be a positive integer")
272		}
273		switch input.Type {
274		case ActionNote, ActionLinkEvent, ActionResolve, ActionReopen,
275			ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
276		default:
277			return Request{}, validationErr("unknown action %q", input.Type)
278		}
279		if input.Content, err = trimRequired(actionContentField(input.Type), input.Content); err != nil {
280			return Request{}, err
281		}
282		return input, nil
283	}
284	
285	// actionContentField names the request member that carries each action's
286	// payload, used in validation messages.
287	func actionContentField(action string) string {
288		switch action {
289		case ActionLinkEvent:
290			return "event_id"
291		case ActionResolve, ActionReopen:
292			return "reason"
293		case ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
294			return "participant"
295		default:
296			return "content"
297		}
298	}
299	
300	func trimRequired(field, value string) (string, error) {
301		value = strings.TrimSpace(value)
302		if value == "" {
303			return "", validationErr("%s must not be empty", field)
304		}
305		return value, nil
306	}
307	
308	// Create accepts a new incident or replays an identical creation. A stored id
309	// presented with different normalized content conflicts.
310	func (r *Registry) Create(input Creation) (CreateResult, error) {
311		creation, err := NormalizeCreation(input)
312		if err != nil {
313			return CreateResult{}, err
314		}
315	
316		r.mu.Lock()
317		defer r.mu.Unlock()
318	
319		if existing, ok := r.incidents[creation.ID]; ok {
320			if existing.creation != creation {
321				return CreateResult{}, conflictErr(existing.version,
322					"incident %q already exists with different content", creation.ID)
323			}
324			// A creation replay returns the first result verbatim: open at
325			// version 1, even if the incident has moved on since.
326			return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
327		}
328	
329		at := r.now()
330		record := NewCreationRecord(creation, at)
331		if r.beforeCommit != nil {
332			if err := r.beforeCommit(record); err != nil {
333				return CreateResult{}, err
334			}
335		}
336		r.incidents[creation.ID] = newIncidentState(creation, at)
337		return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
338	}
339	
340	// Apply accepts one action or replays an identical one. Validation and every
341	// state check happen under the registry lock before persistence, so a
342	// rejected request leaves the incident untouched.
343	func (r *Registry) Apply(input Request) (ActionResult, error) {
344		req, err := NormalizeRequest(input)
345		if err != nil {
346			return ActionResult{}, err
347		}
348	
349		r.mu.Lock()
350		defer r.mu.Unlock()
351	
352		state, ok := r.incidents[req.IncidentID]
353		if !ok {
354			return ActionResult{}, notFoundErr("incident %q not found", req.IncidentID)
355		}
356	
357		// Idempotent replay is checked first: a retry of the first successful
358		// request still returns that result even though its expected_version is
359		// stale by now.
360		if prior, repeated := state.actions[req.ActionID]; repeated {
361			if prior.request != req {
362				return ActionResult{}, conflictErr(state.version,
363					"action %q already exists with different content", req.ActionID)
364			}
365			return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: prior.resultVersion}, nil
366		}
367	
368		if err := r.checkAction(state, req); err != nil {
369			return ActionResult{}, err
370		}
371	
372		at := r.now()
373		if r.beforeCommit != nil {
374			if err := r.beforeCommit(NewActionRecord(req, at)); err != nil {
375				return ActionResult{}, err
376			}
377		}
378		version := state.commit(req, at)
379		return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: version}, nil
380	}
381	
382	// checkAction enforces optimistic versioning, the open/resolved state
383	// machine, and the link rules. It runs with the registry lock held.
384	func (r *Registry) checkAction(state *incidentState, req Request) error {
385		if req.ExpectedVersion != state.version {
386			return conflictErr(state.version,
387				"expected version %d but incident %q is at version %d",
388				req.ExpectedVersion, state.id, state.version)
389		}
390		switch req.Type {
391		case ActionNote:
392			if state.status != StatusOpen {
393				return conflictErr(state.version, "cannot add a note to a %s incident", state.status)
394			}
395		case ActionLinkEvent:
396			if state.status != StatusOpen {
397				return conflictErr(state.version, "cannot link an event to a %s incident", state.status)
398			}
399			if r.events == nil {
400				return notFoundErr("event %q not found", req.Content)
401			}
402			service, found := r.events.LookupEvent(req.Content)
403			if !found {
404				return notFoundErr("event %q not found", req.Content)
405			}
406			if service != state.service {
407				return conflictErr(state.version,
408					"event %q belongs to service %q, not %q", req.Content, service, state.service)
409			}
410			if _, linked := state.linkSet[req.Content]; linked {
411				return conflictErr(state.version,
412					"event %q is already linked to incident %q", req.Content, state.id)
413			}
414		case ActionResolve:
415			if state.status != StatusOpen {
416				return conflictErr(state.version, "incident %q is already resolved", state.id)
417			}
418		case ActionReopen:
419			if state.status != StatusResolved {
420				return conflictErr(state.version, "incident %q is not resolved", state.id)
421			}
422		case ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
423			if state.status != StatusOpen {
424				return conflictErr(state.version, "cannot %s on a %s incident", participantRuleName(req.Type), state.status)
425			}
426			switch req.Type {
427			case ActionAddParticipant:
428				if _, member := state.participantSet[req.Content]; member {
429					return conflictErr(state.version,
430						"%q is already a participant of incident %q", req.Content, state.id)
431				}
432			case ActionRemoveParticipant:
433				if _, member := state.participantSet[req.Content]; !member {
434					return conflictErr(state.version,
435						"%q is not a participant of incident %q", req.Content, state.id)
436				}
437				if req.Content == state.owner {
438					return conflictErr(state.version,
439						"cannot remove the current owner %q from incident %q", req.Content, state.id)
440				}
441			case ActionAssignOwner:
442				if _, member := state.participantSet[req.Content]; !member {
443					return conflictErr(state.version,
444						"cannot hand incident %q to non-participant %q", state.id, req.Content)
445				}
446				if req.Content == state.owner {
447					return conflictErr(state.version,
448						"%q is already the owner of incident %q", req.Content, state.id)
449				}
450			}
451		}
452		return nil
453	}
454	
455	// participantRuleName renders the personnel action names in error messages.
456	func participantRuleName(action string) string {
457		switch action {
458		case ActionAddParticipant:
459			return "add a participant"
460		case ActionRemoveParticipant:
461			return "remove a participant"
462		case ActionAssignOwner:
463			return "hand over ownership"
464		default:
465			return action
466		}
467	}
468	
469	// Get returns a point-in-time copy of one incident. The copy's people,
470	// status, links, version, and history all belong to the same committed
471	// version.
472	func (r *Registry) Get(id string) (Incident, error) {
473		r.mu.Lock()
474		defer r.mu.Unlock()
475		state, ok := r.incidents[id]
476		if !ok {
477			return Incident{}, notFoundErr("incident %q not found", id)
478		}
479		return state.snapshot(), nil
480	}
481	
482	func newIncidentState(creation Creation, at time.Time) *incidentState {
483		return &incidentState{
484			id:             creation.ID,
485			title:          creation.Title,
486			service:        creation.Service,
487			status:         StatusOpen,
488			version:        1,
489			participants:   []string{creation.Operator},
490			participantSet: map[string]struct{}{creation.Operator: {}},
491			owner:          creation.Operator,
492			links:          []string{},
493			linkSet:        make(map[string]struct{}),
494			actions:        make(map[string]committedAction),
495			history:        []Entry{{Operator: creation.Operator, Action: ActionCreate, Content: creation.Title, Version: 1, At: at}},
496			creation:       creation,
497		}
498	}
499	
500	// commit advances the state by one already-validated action and returns the
501	// new version.
502	func (s *incidentState) commit(req Request, at time.Time) int {
503		switch req.Type {
504		case ActionLinkEvent:
505			s.linkSet[req.Content] = struct{}{}
506			s.links = append(s.links, req.Content)
507		case ActionResolve:
508			s.status = StatusResolved
509		case ActionReopen:
510			s.status = StatusOpen
511		case ActionAddParticipant:
512			s.participantSet[req.Content] = struct{}{}
513			s.participants = append(s.participants, req.Content)
514		case ActionRemoveParticipant:
515			delete(s.participantSet, req.Content)
516			s.participants = removeString(s.participants, req.Content)
517		case ActionAssignOwner:
518			s.owner = req.Content
519		}
520		s.version++
521		s.history = append(s.history, Entry{
522			ActionID: req.ActionID,
523			Operator: req.Operator,
524			Action:   req.Type,
525			Content:  req.Content,
526			Version:  s.version,
527			At:       at,
528		})
529		s.actions[req.ActionID] = committedAction{request: req, resultVersion: s.version}
530		return s.version
531	}
532	
533	// removeString drops the first occurrence of value, preserving order.
534	func removeString(values []string, value string) []string {
535		for i, v := range values {
536			if v == value {
537				return append(values[:i], values[i+1:]...)
538			}
539		}
540		return values
541	}
542	
543	func (s *incidentState) snapshot() Incident {
544		links := slices.Clone(s.links)
545		history := make([]Entry, len(s.history))
546		copy(history, s.history)
547		participants := append([]string{}, s.participants...)
548		slices.Sort(participants)
549		return Incident{
550			ID:           s.id,
551			Title:        s.title,
552			Service:      s.service,
553			Status:       s.status,
554			Version:      s.version,
555			Participants: participants,
556			Owner:        s.owner,
557			Links:        links,
558			History:      history,
559		}
560	}
