54		// Duplicate add is a 409-style conflict carrying the current version.
55		_, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p3", Operator: "alice",
56			ExpectedVersion: 3, Type: ActionAddParticipant, Content: "bob"})
57		if !IsConflictError(err) || CurrentVersionOf(err) != 3 {
58			t.Fatalf("duplicate add: %v", err)
59		}
60	
61		// Names differing only in case are distinct people.
62		add("p4", 3, "Bob")
63		inc, _ = reg.Get("INC-1")
