86		// The current owner cannot be removed; a non-owner participant can.
87		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "p5", Operator: "alice",
88			ExpectedVersion: 5, Type: ActionRemoveParticipant, Content: "Carol"})
89		if !IsConflictError(err) || CurrentVersionOf(err) != 5 {
90			t.Fatalf("remove owner: %v", err)
91		}
92		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p6", Operator: "alice",
93			ExpectedVersion: 5, Type: ActionRemoveParticipant, Content: "stranger"}); !IsConflictError(err) {
94			t.Fatalf("remove non-member: %v", err)
95		}
96		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p7", Operator: "alice",
97			ExpectedVersion: 5, Type: ActionAssignOwner, Content: "stranger"}); !IsConflictError(err) {
98			t.Fatalf("assign non-member: %v", err)
99		}
100		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p8", Operator: "alice",
101			ExpectedVersion: 5, Type: ActionAssignOwner, Content: "Carol"}); !IsConflictError(err) {
102			t.Fatalf("assign current owner: %v", err)
103		}
104	
105		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p9", Operator: "alice",
106			ExpectedVersion: 5, Type: ActionRemoveParticipant, Content: "bob"}); err != nil {
107			t.Fatalf("remove member: %v", err)
108		}
109		inc, _ = reg.Get("INC-1")
110		if inc.Owner != "Carol" {
111			t.Fatalf("owner must survive removals: %q", inc.Owner)
112		}
113		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Bob", "Carol"}) {
114			t.Fatalf("membership after remove: %+v", inc.Participants)
115		}
116	
117		// Rejected actions leave version/history untouched: version moved 1->6
118		// through p1, p2, p4, o1, p9 only.
119		if inc.Version != 6 {
120			t.Fatalf("version after accepted actions %d", inc.Version)
121		}
122		if len(inc.History) != 6 {
123			t.Fatalf("history after accepted actions %d", len(inc.History))
124		}
125		if commit.count() != 6 {
126			t.Fatalf("durable records %d", commit.count())
127		}
