173			"blank participant": func(r Request) Request { r.Content = "  "; return r },
174			"remove blank":      func(r Request) Request { r.Type = ActionRemoveParticipant; r.Content = "\t"; return r },
175			"assign blank":      func(r Request) Request { r.Type = ActionAssignOwner; r.Content = ""; return r },
