	add := func(actionID string, version int, name string) {
		t.Helper()
		res, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: actionID, Operator: "alice",
			ExpectedVersion: version, Type: ActionAddParticipant, Content: name})
